package com.mepatrick73.ringmenu;

import java.awt.Font;
import java.util.function.Supplier;
import lombok.AllArgsConstructor;
import net.runelite.client.ui.FontManager;

@AllArgsConstructor
public enum RingFontType
{
	// RuneScape fonts derive from the bundled glyphs loaded by FontManager.
	RUNESCAPE("RuneScape", FontManager::getRunescapeFont, null),
	RUNESCAPE_SMALL("RuneScape Small", FontManager::getRunescapeSmallFont, null),
	RUNESCAPE_BOLD("RuneScape Bold", FontManager::getRunescapeBoldFont, null),
	// System fonts are resolved by family name; Java falls back to a default if not installed.
	ARIAL("Arial", null, "Arial"),
	CAMBRIA("Cambria", null, "Cambria"),
	ROCKWELL("Rockwell", null, "Rockwell"),
	SEGOE_UI("Segoe UI", null, "Segoe UI"),
	TIMES_NEW_ROMAN("Times New Roman", null, "Times New Roman"),
	VERDANA("Verdana", null, "Verdana");

	private final String label;
	private final Supplier<Font> baseFont; // RuneScape fonts: derive from this loaded font
	private final String family;           // system fonts: resolve by family name

	public Font getFont(int size)
	{
		return baseFont != null
			? baseFont.get().deriveFont((float) size)
			: new Font(family, Font.PLAIN, size);
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.mepatrick73.ringmenu;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.reflect.TypeToken;
import com.mepatrick73.ringmenu.data.RingDefinition;
import com.mepatrick73.ringmenu.data.RingTreeEntry;
import com.mepatrick73.ringmenu.data.StoredRings;
import com.mepatrick73.ringmenu.data.TextOrientation;
import com.mepatrick73.ringmenu.engine.model.RingAction;
import com.mepatrick73.ringmenu.engine.model.RingEntry;
import com.mepatrick73.ringmenu.engine.model.RingNode;
import com.mepatrick73.ringmenu.engine.runtime.RingController;
import com.mepatrick73.ringmenu.engine.runtime.RingMenuOverlay;
import com.mepatrick73.ringmenu.providers.RingProvider;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.vars.InputType;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Point;
import java.awt.event.KeyEvent;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Slf4j
@Singleton
public class RingManager
{
	private static final String CONFIG_GROUP    = "ringmenu";
	private static final String CONFIG_KEY_RINGS = "rings";

	// Schema version of the saved ring list. Bump only alongside a migration in load(). Version 0 is the
	// legacy pre-envelope format: a bare JSON array of RingDefinition, written by plugin <= 1.0.2.
	private static final int CONFIG_VERSION = 1;
	private static final int CONFIG_VERSION_LEGACY = 0;

	// Sentinel the KeyRemapping plugin writes into the chatbox input while "Press Enter to Chat"
	// is locked/idle. Its presence means a character key won't type, so it may open the ring.
	private static final String PRESS_ENTER_TO_CHAT = "Press Enter to Chat...";

	@Inject private ConfigManager configManager;
	@Inject private KeyManager keyManager;
	@Inject private RingController ringController;
	@Inject private RingMenuOverlay overlay;
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private Gson gson;

	private final List<RingDefinition> rings     = new ArrayList<>();
	private final Map<String, KeyListener> listeners = new HashMap<>();
	private List<RingProvider> providers = new ArrayList<>();

	// The definition the open ring was built from, so editor changes to it can be pushed into the
	// live ring. Never cleared on close — only meaningful while ringController.isOpen().
	private volatile RingDefinition openRingDef;

	// Set when the stored rings could not be read (corrupt JSON, or written by a newer version we do not
	// understand). While set, save() refuses to write: overwriting would destroy rings we failed to parse.
	private boolean loadFailed;

	// Set when load() read a pre-envelope value, so it can be rewritten in the current format right away
	// instead of waiting for the user's next edit.
	private boolean loadedLegacy;

	// Typing context, computed on the client thread (see updateInputState) and read from the AWT
	// key-dispatch thread. Reading widget/varc state directly in the key listener can be momentarily
	// out of sync with the client thread, so we cache it here instead.
	private volatile boolean inputFieldActive; // a text prompt owns the keyboard (search, PM, input widget)
	private volatile boolean chatTypeable;     // a character key would type into the chatbox right now

	public void setProviders(List<RingProvider> providers)
	{
		this.providers = providers;
	}

	public void load()
	{
		loadFailed = false;
		loadedLegacy = false;
		String json = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY_RINGS);
		if (json != null && !json.isEmpty())
		{
			try
			{
				List<RingDefinition> loaded = parse(json);
				if (loaded != null)
				{
					rings.addAll(loaded);
				}
			}
			catch (Exception e)
			{
				// Keep the stored value intact — save() stays disabled until a successful load.
				loadFailed = true;
				log.warn("Failed to load rings; leaving the saved config untouched", e);
			}
		}
		if (loadedLegacy)
		{
			// Migrate on read rather than on the next edit, so the stored value is never left behind in a
			// format this plugin no longer writes.
			log.debug("Migrating stored rings from v{} to v{}", CONFIG_VERSION_LEGACY, CONFIG_VERSION);
			save();
		}
		rings.forEach(this::registerListener);
		providers.forEach(RingProvider::onLoad);
	}

	// Reads either the versioned envelope or the legacy bare array. Throws when the value is unreadable
	// or newer than we understand, which load() turns into the no-overwrite guard.
	private List<RingDefinition> parse(String json)
	{
		JsonElement root = gson.fromJson(json, JsonElement.class);
		if (root == null || root.isJsonNull())
		{
			return null;
		}
		if (root.isJsonArray())
		{
			// Legacy format — load() rewrites it as a versioned envelope straight away.
			loadedLegacy = true;
			Type listType = new TypeToken<List<RingDefinition>>()
			{
			}.getType();
			return gson.fromJson(root, listType);
		}

		StoredRings envelope = gson.fromJson(root, StoredRings.class);
		if (envelope.getVersion() > CONFIG_VERSION)
		{
			throw new IllegalStateException("Saved rings are version " + envelope.getVersion()
				+ ", this plugin understands up to " + CONFIG_VERSION);
		}
		if (envelope.getRings() == null)
		{
			// An envelope with no ring list is not an empty ring list, it is a value we don't understand.
			throw new IllegalStateException("Saved rings v" + envelope.getVersion() + " has no ring list");
		}
		return envelope.getRings();
	}

	public void unload()
	{
		// Providers are singletons that outlive a plugin disable/enable; drop the editor callback so a
		// stale panel is never called back after shutdown.
		providers.forEach(p -> p.setChangeListener(null));
		providers.forEach(RingProvider::onUnload);
		listeners.values().forEach(keyManager::unregisterKeyListener);
		listeners.clear();
		rings.clear();
	}

	public List<RingDefinition> getRings()
	{
		return rings;
	}

	public List<RingProvider> getProviders()
	{
		return providers;
	}

	public RingDefinition addRing(String name)
	{
		RingDefinition ring = RingDefinition.create(name);
		rings.add(ring);
		registerListener(ring);
		save();
		return ring;
	}

	public void removeRing(RingDefinition ring)
	{
		rings.remove(ring);
		KeyListener listener = listeners.remove(ring.getId());
		if (listener != null) keyManager.unregisterKeyListener(listener);
		save();
	}

	public void save()
	{
		if (loadFailed)
		{
			log.warn("Not saving rings: the stored config could not be read, so writing would discard it");
			return;
		}
		configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY_RINGS,
			gson.toJson(new StoredRings(CONFIG_VERSION, rings)));
	}

	// True when the stored rings could not be read. Edits are kept in memory but never written, so the
	// editor must tell the user rather than letting them rebuild rings that will not survive a restart.
	public boolean isLoadFailed()
	{
		return loadFailed;
	}

	// True when the entry points at something its provider no longer knows about — a deleted or renamed
	// Inventory Setup, say. Sub-rings report missing when anything inside them does.
	public boolean isEntryMissing(RingTreeEntry entry)
	{
		if (entry.isSubRing())
		{
			// Disabled children never reach the ring, so they don't make the sub-ring unhealthy.
			return entry.getChildren().stream()
				.filter(RingTreeEntry::isEnabled)
				.anyMatch(this::isEntryMissing);
		}
		RingProvider provider = findProvider(entry.getProviderId());
		// No provider at all means buildRingNode drops the entry from the ring entirely, so it is broken
		// in the strongest sense — never render it as healthy.
		return provider == null || !provider.isEntryValid(entry);
	}

	// Recomputes the typing context. MUST be called on the client thread (driven by ClientTick),
	// where widget and varc reads are consistent. Mirrors the signals used by RuneLite's
	// KeyRemapping / chat plugins.
	public void updateInputState()
	{
		// An INPUT_FIELD widget owns the keyboard (GE quantity, fairy ring code, etc.), or a
		// message-layer prompt is open: bank/GE search (SEARCH) or private message input.
		inputFieldActive = client.getFocusedInputFieldWidget() != null
			|| client.getVarcIntValue(VarClientID.MESLAYERMODE) != InputType.NONE.getType();

		// A character key types into regular chat only when the chatbox is accepting input and is
		// not sitting idle under KeyRemapping's "Press Enter to Chat" lock.
		Widget chatbox = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		chatTypeable = chatbox != null && chatbox.getOnKeyListener() != null && !isPressEnterToChatIdle();
	}

	// True when KeyRemapping's "Press Enter to Chat" lock is active and idle (not mid-message),
	// detected by the sentinel text it places in the chatbox input widget.
	private boolean isPressEnterToChatIdle()
	{
		Widget input = client.getWidget(InterfaceID.Chatbox.INPUT);
		return input != null && input.getText() != null && input.getText().endsWith(PRESS_ENTER_TO_CHAT);
	}

	// Returns true when this keypress should fall through to the game instead of opening the ring,
	// because the player is (or could be) typing it into a text input. Reads only the cached flags
	// computed by updateInputState, so it is safe to call from the AWT key-dispatch thread.
	private boolean isTyping(KeyEvent e)
	{
		// A text prompt owns the keyboard — suppress every key.
		if (inputFieldActive) return true;

		// Ctrl/Alt/Meta combos never produce a typed character, and non-character keys (F-keys, etc.)
		// are handled by OSRS even while the chatbox is active — let all of those open the ring.
		if ((e.getModifiersEx() & (KeyEvent.CTRL_DOWN_MASK | KeyEvent.ALT_DOWN_MASK | KeyEvent.META_DOWN_MASK)) != 0)
		{
			return false;
		}
		if (!isCharacterKey(e.getKeyCode())) return false;

		return chatTypeable;
	}

	private static boolean isCharacterKey(int keyCode)
	{
		if (keyCode >= KeyEvent.VK_A && keyCode <= KeyEvent.VK_Z) return true;
		if (keyCode >= KeyEvent.VK_0 && keyCode <= KeyEvent.VK_9) return true;
		if (keyCode >= KeyEvent.VK_NUMPAD0 && keyCode <= KeyEvent.VK_NUMPAD9) return true;
		return keyCode == KeyEvent.VK_SPACE
			|| keyCode == KeyEvent.VK_COMMA
			|| keyCode == KeyEvent.VK_PERIOD
			|| keyCode == KeyEvent.VK_SLASH
			|| keyCode == KeyEvent.VK_SEMICOLON
			|| keyCode == KeyEvent.VK_EQUALS
			|| keyCode == KeyEvent.VK_MINUS
			|| keyCode == KeyEvent.VK_OPEN_BRACKET
			|| keyCode == KeyEvent.VK_CLOSE_BRACKET
			|| keyCode == KeyEvent.VK_BACK_SLASH
			|| keyCode == KeyEvent.VK_QUOTE
			|| keyCode == KeyEvent.VK_BACK_QUOTE;
	}

	private void registerListener(RingDefinition ring)
	{
		KeyListener listener = new RingKeyListener(ring);
		keyManager.registerKeyListener(listener);
		listeners.put(ring.getId(), listener);
	}

	// Custom KeyListener instead of HotkeyListener: HotkeyListener always consumes a matching
	// keypress, which would swallow the character before it could reach the chatbox. We only
	// consume when the ring actually opens, so a hotkey key still types in chat when appropriate.
	private final class RingKeyListener implements KeyListener
	{
		private final RingDefinition ring;
		private boolean consumingTyped;

		RingKeyListener(RingDefinition ring)
		{
			this.ring = ring;
		}

		@Override
		public void keyTyped(KeyEvent e)
		{
			if (consumingTyped)
			{
				e.consume();
			}
		}

		@Override
		public void keyPressed(KeyEvent e)
		{
			if (!ring.getHotkey().matches(e))
			{
				return;
			}

			if (!ring.isEnabled() || isTyping(e))
			{
				// Let the keypress fall through to the game (e.g. typing in chat).
				return;
			}

			if (ringController.isOpen())
			{
				ringController.close();
			}
			else
			{
				overlay.setCenter(new Point(client.getCanvasWidth() / 2, client.getCanvasHeight() / 2));
				openRingDef = ring;
				ringController.open(buildRoot(ring));
			}

			// Consume so the key doesn't also reach the game. Modifier keys are never consumed.
			if (Keybind.getModifierForKeyCode(e.getKeyCode()) == null)
			{
				consumingTyped = true;
				e.consume();
			}
		}

		@Override
		public void keyReleased(KeyEvent e)
		{
			if (ring.getHotkey().matches(e))
			{
				consumingTyped = false;
			}
		}
	}

	// Pushes the current (possibly unsaved) state of the given definition into the ring, if that ring
	// is the one open right now. The user's position in sub-rings is kept where the levels still
	// exist. Called from the editor on the EDT after every edit.
	public void refreshOpenRing(RingDefinition ring)
	{
		if (ring == null || ring != openRingDef || !ringController.isOpen())
		{
			return;
		}
		ringController.replaceRoot(buildRoot(ring));
	}

	private RingNode buildRoot(RingDefinition ring)
	{
		return buildRingNode(ring.getEntries(), ring.getName(), ring.getTextOrientation());
	}

	private RingNode buildRingNode(List<RingTreeEntry> entries, String label, TextOrientation orientation)
	{
		RingNode node = new RingNode(label);
		node.setTextOrientation(orientation);
		for (RingTreeEntry entry : entries)
		{
			if (!entry.isEnabled()) continue;
			if (entry.isSubRing())
			{
				RingNode child = buildRingNode(entry.getChildren(), entry.getLabel(), entry.getTextOrientation());
				child.setMissing(child.getChildren().stream().anyMatch(RingEntry::isMissing));
				node.getChildren().add(child);
			}
			else
			{
				RingProvider provider = findProvider(entry.getProviderId());
				if (provider == null) continue;
				Runnable action = provider.buildAction(entry);
				// RingAction.onSelect() already calls controller.close() before invoking the action.
				node.getChildren().add(new RingAction(entry.getLabel(), () ->
				{
					providers.forEach(RingProvider::deactivate);
					// Selection arrives on the AWT mouse thread; provider actions touch client state.
					clientThread.invoke(action);
				}, !provider.isEntryValid(entry)));
			}
		}
		return node;
	}

	private RingProvider findProvider(String id)
	{
		return providers.stream().filter(p -> p.getId().equals(id)).findFirst().orElse(null);
	}
}

package com.mepatrick73.ringmenu;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(RingMenuConfig.GROUP)
public interface RingMenuConfig extends Config
{
	String GROUP = "ringmenu";

	@Range(
		min = 80,
		max = 250
	)
	@ConfigItem(
		keyName = "ringRadius",
		name = "Ring size",
		description = "Radius of the ring menu, in pixels. The inner circle scales with it.",
		position = 0
	)
	default int ringRadius()
	{
		return 135;
	}

	@ConfigItem(
		keyName = "fontType",
		name = "Font",
		description = "Font used for the ring menu labels",
		position = 1
	)
	default RingFontType fontType()
	{
		return RingFontType.RUNESCAPE;
	}

	@Range(
		min = 8,
		max = 40
	)
	@ConfigItem(
		keyName = "fontSize",
		name = "Font size",
		description = "Size of the ring menu label text",
		position = 2
	)
	default int fontSize()
	{
		return 17;
	}

	@ConfigItem(
		keyName = "shrinkTextToFit",
		name = "Shrink text to fit",
		description = "Reduce the label font size (down to a minimum) so long names fit in their slice before truncating",
		position = 3
	)
	default boolean shrinkTextToFit()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hoverTooltip",
		name = "Full name on hover",
		description = "Show the full entry name in a tooltip when hovering a slice whose label is shortened",
		position = 4
	)
	default boolean hoverTooltip()
	{
		return true;
	}
}

package com.mepatrick73.ringmenu;

import com.google.inject.Provides;
import com.mepatrick73.ringmenu.editor.RingEditorPanel;
import com.mepatrick73.ringmenu.engine.runtime.RingController;
import com.mepatrick73.ringmenu.engine.runtime.RingMenuOverlay;
import com.mepatrick73.ringmenu.providers.BankTagsProvider;
import com.mepatrick73.ringmenu.providers.InventorySetupsProvider;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import java.awt.event.MouseEvent;
import java.util.List;

@PluginDependency(BankTagsPlugin.class)
@PluginDescriptor(
	name = "Ring Menu",
	description = "Radial ring menu for quickly accessing bank tags and inventory setups",
	tags = {"ring", "menu", "radial", "bank", "inventory", "setups"}
)
public class RingMenuPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private RingController ringController;
	@Inject private RingMenuOverlay overlay;
	@Inject private OverlayManager overlayManager;
	@Inject private MouseManager mouseManager;
	@Inject private InventorySetupsProvider inventorySetupsProvider;
	@Inject private BankTagsProvider bankTagsProvider;
	@Inject private RingManager ringManager;
	@Inject private RingEditorPanel editorPanel;
	@Inject private ClientToolbar clientToolbar;

	private volatile NavigationButton navButton;

	private final MouseAdapter mouseListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			if (!ringController.isOpen()) return event;

			if (SwingUtilities.isRightMouseButton(event))
			{
				ringController.close();
				event.consume();
				return event;
			}

			if (SwingUtilities.isLeftMouseButton(event))
			{
				if (overlay.isOutsideRing(event.getX(), event.getY()))
				{
					ringController.close();
					event.consume();
					return event;
				}

				int idx = overlay.getHighlightedIndex();
				if (idx >= 0)
				{
					ringController.currentEntries().get(idx).onSelect(ringController);
				}
				else if (ringController.canGoBack())
				{
					ringController.back();
				}
				else
				{
					clientThread.invoke(() ->
						ringManager.getProviders().forEach(p ->
						{
							Runnable cancel = p.cancelAction();
							if (cancel != null) cancel.run();
						})
					);
					ringController.close();
				}
				event.consume();
				return event;
			}

			return event;
		}
	};

	@Provides
	RingMenuConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RingMenuConfig.class);
	}

	@Override
	protected void startUp()
	{
		ringManager.setProviders(List.of(inventorySetupsProvider, bankTagsProvider));
		ringManager.getProviders().forEach(p -> p.setChangeListener(editorPanel::refreshProviderEntries));
		ringManager.load();
		overlayManager.add(overlay);
		mouseManager.registerMouseListener(mouseListener);
		SwingUtilities.invokeLater(() ->
		{
			editorPanel.rebuildRingRows();
			navButton = NavigationButton.builder()
				.tooltip("Ring Menu")
				.icon(ImageUtil.loadImageResource(getClass(), "ring_icon.png"))
				.priority(6)
				.panel(editorPanel)
				.build();
			clientToolbar.addNavigation(navButton);
		});
	}

	@Override
	protected void shutDown()
	{
		mouseManager.unregisterMouseListener(mouseListener);
		overlayManager.remove(overlay);
		ringController.close();
		ringManager.unload();
		SwingUtilities.invokeLater(() ->
		{
			if (navButton != null) clientToolbar.removeNavigation(navButton);
		});
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		ringManager.updateInputState();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!ringController.isOpen()) return;
		Point mouse = client.getMouseCanvasPosition();
		if (!overlay.isOutsideRing(mouse.getX(), mouse.getY()))
		{
			client.getMenu().setMenuEntries(new MenuEntry[0]);
		}
	}
}

package com.mepatrick73.ringmenu.data;

import lombok.AccessLevel;
import lombok.Data;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.config.Keybind;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

@Data
public class RingDefinition
{
	private String id;
	private String name;
	// Stored as plain ints so Gson can (de)serialize them.
	// Keybind has final fields + no no-args constructor, which breaks Gson on Java 17+.
	// Use setHotkey(Keybind) to write these fields — raw setters are suppressed.
	@Setter(AccessLevel.NONE)
	private int hotkeyCode      = 0;
	@Setter(AccessLevel.NONE)
	private int hotkeyModifiers = 0;
	// Boxed Boolean so missing field in old JSON deserializes as null (treated as true).
	private Boolean enabled;
	// How the root ring draws its slice labels. Stored as null when it is the default
	// (HORIZONTAL) so old plugin versions and old JSON round-trip cleanly.
	@Getter(AccessLevel.NONE)
	@Setter(AccessLevel.NONE)
	private TextOrientation textOrientation;
	private List<RingTreeEntry> entries;

	public Keybind getHotkey()
	{
		return new Keybind(hotkeyCode, hotkeyModifiers);
	}

	public void setHotkey(Keybind kb)
	{
		if (kb == null || kb.equals(Keybind.NOT_SET))
		{
			hotkeyCode      = 0;
			hotkeyModifiers = 0;
		}
		else
		{
			hotkeyCode      = kb.getKeyCode();
			hotkeyModifiers = kb.getModifiers();
		}
	}

	public boolean hasHotkey()
	{
		return !getHotkey().equals(Keybind.NOT_SET);
	}

	public TextOrientation getTextOrientation()
	{
		return TextOrientation.orDefault(textOrientation);
	}

	public void setTextOrientation(TextOrientation orientation)
	{
		textOrientation = TextOrientation.storedForm(orientation);
	}

	public boolean isEnabled()
	{
		return enabled == null || enabled;
	}

	public void setEnabled(boolean value)
	{
		enabled = value ? null : Boolean.FALSE;
	}

	public List<RingTreeEntry> getEntries()
	{
		if (entries == null) entries = new ArrayList<>();
		return entries;
	}

	public static RingDefinition create(String name)
	{
		RingDefinition r = new RingDefinition();
		r.id      = UUID.randomUUID().toString();
		r.name    = name;
		r.entries = new ArrayList<>();
		return r;
	}
}

