	// Shown when the saved rings could not be read. Saving is disabled in that state so the stored value
	// is not overwritten, which means anything built here is lost on restart — say so rather than letting
	// the panel look like a fresh, empty install.
	private JPanel buildLoadFailedBanner()
	{
		JPanel banner = new JPanel(new BorderLayout());
		banner.setBackground(BG_DARK);
		banner.setBorder(new CompoundBorder(
			new MatteBorder(0, 2, 0, 0, TEXT_MISSING), new EmptyBorder(6, 8, 6, 8)));
		JLabel lbl = new JLabel("<html><b>Your saved rings could not be read.</b><br>"
			+ "They have been left untouched and nothing you change here will be saved. "
			+ "Check the client log, then restart.</html>");
		lbl.setForeground(TEXT_MISSING);
		lbl.setFont(FontManager.getRunescapeSmallFont());
		banner.add(lbl, BorderLayout.CENTER);
		return banner;
	}

	public void rebuildRingRows()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::rebuildRingRows);
			return;
		}
		ringRows.removeAll();
		if (ringManager.isLoadFailed())
		{
			ringRows.add(buildLoadFailedBanner());
			ringRows.add(Box.createVerticalStrut(4));
		}
		for (RingDefinition ring : ringManager.getRings())
		{
			ringRows.add(buildRingRow(ring));
			ringRows.add(Box.createVerticalStrut(4));
		}
		ringRows.revalidate();
		ringRows.repaint();
	}

	private JPanel buildRingRow(RingDefinition ring)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(BG_DARK);
		row.setBorder(new CompoundBorder(
			new MatteBorder(0, 3, 0, 0, ACCENT), new EmptyBorder(5, 8, 5, 6)));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 46));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		JLabel name = new JLabel(ring.getName());
		name.setFont(FontManager.getRunescapeFont());
		name.setForeground(ring.isEnabled() ? TEXT : TEXT_DIM);

		String hkTxt = ring.hasHotkey() ? ring.getHotkey().toString() : "no key";
		JLabel hk = new JLabel(hkTxt);
		hk.setFont(FontManager.getRunescapeSmallFont());
		hk.setForeground(TEXT_DIM);

		JPanel labels = new JPanel(new GridLayout(2, 1));
		labels.setBackground(BG_DARK);
		labels.add(name);
		labels.add(hk);

		JButton pen = smallBtn("✎");
		pen.setForeground(TEXT_DIM);
		pen.addActionListener(e ->
		{
			String newName = (String) JOptionPane.showInputDialog(
				this, null, "Rename Ring", JOptionPane.PLAIN_MESSAGE, null, null, ring.getName());
			if (newName == null || newName.trim().isEmpty()) return;
			ring.setName(newName.trim());
			ringManager.save();
			ringManager.refreshOpenRing(ring);
			rebuildRingRows();
		});

		JButton del = smallBtn("×");
		del.setForeground(TEXT_DIM);
		del.addActionListener(e ->
		{
			int ok = JOptionPane.showConfirmDialog(this,
				"Delete ring \"" + ring.getName() + "\"?",
				"Delete Ring", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
			if (ok != JOptionPane.YES_OPTION) return;
			ringManager.removeRing(ring);
			rebuildRingRows();
		});

		JCheckBox enabledBox = new JCheckBox();
		enabledBox.setSelected(ring.isEnabled());
		enabledBox.setBackground(BG_DARK);
		enabledBox.setFocusPainted(false);
		enabledBox.setToolTipText("Enable / disable this ring");
		enabledBox.addActionListener(e ->
		{
			ring.setEnabled(enabledBox.isSelected());
			ringManager.save();
			name.setForeground(ring.isEnabled() ? TEXT : TEXT_DIM);
		});

		JPanel actions = new JPanel();
		actions.setLayout(new BoxLayout(actions, BoxLayout.X_AXIS));
		actions.setBackground(BG_DARK);
		actions.add(enabledBox);
		actions.add(pen);
		actions.add(del);

		row.add(labels, BorderLayout.CENTER);
		row.add(actions, BorderLayout.EAST);
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				selectRing(ring);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(BG_MED);
				labels.setBackground(BG_MED);
				actions.setBackground(BG_MED);
				pen.setBackground(BG_MED);
				del.setBackground(BG_MED);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(BG_DARK);
				labels.setBackground(BG_DARK);
				actions.setBackground(BG_DARK);
				pen.setBackground(BG_DARK);
				del.setBackground(BG_DARK);
			}
		});
		return row;
	}

